/* Minneoats v2 · page layer: home, ingredient bowl, Minne Trio, Minne Morning Box, Minne Club, gifts. */
const wave=(a,b,flip)=>`<div class="wave" style="background:${b}"><svg viewBox="0 0 1440 70" preserveAspectRatio="none" aria-hidden="true"${flip?' style="transform:scaleY(-1)"':''}><path d="M0 0H1440V30C1320 62 1200 68 1080 46S840 6 720 24 480 70 360 56 120 10 0 40Z" fill="${a}"/></svg></div>`;
const pol=(img,cap,r,extra='')=>`<figure class="pol solo rv" style="--r:${r}deg;${extra}"><img src="${A(img)}" alt="" loading="lazy"><figcaption class="hand">${cap}</figcaption></figure>`;
const price=(n)=>money(n).replace('.00','');
function buyPanel(p,label,after){return `<div class="buyp" data-id="${p.id}"><div class="price" id="pprice" data-after=" <small style='font:400 1rem var(--sans);color:var(--clay)'>${after}</small>">${money(p.v[0][2])} <small style="font:400 1rem var(--sans);color:var(--clay)">${after}</small></div><div class="field"><label>${label}</label></div><div class="opt" id="opts">${p.v.map((v,i)=>`<button class="${i==0?'on':''}" data-v="${v[0]}">${v[1]}<br><small>${money(v[2])}</small></button>`).join('')}</div><div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div class="qty"><button id="qm">−</button><span id="qn">1</span><button id="qp">+</button></div><button class="btn pop" id="addbtn" style="flex:1;min-width:200px">Add to bag</button></div><p style="font-size:13.5px;color:var(--mute);margin-top:12px">Discounts do not stack. Shipping calculated at checkout.</p></div>`}
function bagFan(h){const b=A('cut-10oz.webp');return `<div class="fan" style="--h:${h||'100%'}"><img src="${b}" alt="" style="--r:-9deg;--x:12%"><img src="${b}" alt="MINNEØATS Maple Almond Granola, three bags" style="z-index:2;--s:1.08"><img src="${b}" alt="" style="--r:9deg;--x:-12%"></div>`}
function hl(k,h,lead,extra){return `<span class="k">${k}</span><h2 style="margin:12px 0 14px">${h}</h2>${lead?`<p class="lead">${lead}</p>`:''}${extra||''}`}

/* ---------- ingredient bowl ---------- */
const BOWL=[['Organic rolled oats','ing3-oats.jpg','Organic whole rolled oats, never instant or quick-cooking, with a little organic millet for a light crunch.','Fiber, including beta-glucan, supports heart health and keeps you full.','Thick flakes bake into big, sturdy clusters.'],
['Almonds','ing3-almonds.jpg','Whole almonds, toasted in every batch, never almond flavoring.','Vitamin E, protein, fiber and heart-friendly fats.','Real nuts you can see and bite, not a dusting of crumbs.'],
['Maple syrup','ing3-maple.jpg','Organic Grade A maple syrup.','A natural sweetener with manganese, zinc and antioxidants.','It sweetens the granola in place of refined white sugar or corn syrup.'],
['Coconut sugar','ing3-sugar.jpg','Organic coconut sugar, made from coconut palm sap.','Less refined than white sugar, with trace minerals from the palm.','A deep, caramel sweetness that pairs with the maple.'],
['Coconut & coconut oil','ing3-coconut.jpg','Unsweetened coconut flakes and organic virgin coconut oil.','Fiber and fats that keep you satisfied.','Toasty, tender crunch without a candied sweetness. The oil helps the clusters crisp.'],
['Vanilla','ing4-vanilla.jpg','A little vanilla to round things out.','Natural antioxidants and a sweet aroma.','It makes the maple and cinnamon taste warmer.'],
['Cinnamon','ing3-cinnamon.jpg','Ground cinnamon, just the spice.','Packed with antioxidants and warmth without added sugar.','Warmth from a pantry spice, not a flavor additive.'],
['Himalayan pink salt','ing4-salt.jpg','Himalayan pink salt.','Contains trace minerals.','A small pinch balances the sweetness so every bite tastes bigger.']];
function bowlHTML(){return `<div class="bowlx" id="bowlx" role="group" aria-label="A bowl of MINNEØATS granola surrounded by its ingredients. Hover, focus or tap an ingredient to learn why it is in there."><div class="bx-bowl"><img src="${A('gr-yogurt.jpg')}" alt="A bowl of maple almond granola with yogurt"></div><div class="bx-card" id="bxc" aria-live="polite"></div>${BOWL.map((g,i)=>{const a=(-90+22.5+i*45)*Math.PI/180;return `<button type="button" class="bxd" data-i="${i}" style="left:${(50+41*Math.cos(a)).toFixed(1)}%;top:${(50+39*Math.sin(a)).toFixed(1)}%"><span class="dsc"><img ${g[1]==='ing4-salt.jpg'?`data-src="${A(g[1])}" src="data:image/gif;base64,R0lGODlhAQABAAAAACw="`:`src="${A(g[1])}"`} alt="" loading="lazy"></span><span class="lbl">${g[0]}</span></button>`}).join('')}</div><p class="hand bx-hint" id="bxh">hover or tap an ingredient to see why it’s in there</p>`}
function bowlInit(){const box=$('#bowlx');if(!box)return;const card=$('#bxc'),hint=$('#bxh');let cur=-1;const show=i=>{if(i===cur)return;cur=i;const g=BOWL[i];card.innerHTML=`<img src="${i===7?'':A(g[1])}" alt="" hidden><span class="k" style="justify-content:center">Why it’s in there</span><h4>${g[0]}</h4><p>${g[2]}</p><p class="good"><b>The good stuff:</b> ${g[3]}</p><p>${g[4]}</p>`;card.classList.add('on');box.classList.add('has');$$('.bxd',box).forEach(b=>b.classList.toggle('on',+b.dataset.i===i));hint.style.opacity=0};const hide=()=>{cur=-1;card.classList.remove('on');box.classList.remove('has');$$('.bxd',box).forEach(b=>b.classList.remove('on'));hint.style.opacity=1};
 box.addEventListener('mouseover',e=>{const b=e.target.closest('.bxd');if(b)show(+b.dataset.i)});box.addEventListener('focusin',e=>{const b=e.target.closest('.bxd');if(b)show(+b.dataset.i)});box.addEventListener('mouseleave',()=>{if(matchMedia('(hover:hover)').matches)hide()});box.addEventListener('click',e=>{const b=e.target.closest('.bxd');if(!b){hide();return}const i=+b.dataset.i;if(cur===i&&!matchMedia('(hover:hover)').matches)hide();else show(i)});
 show(0);hide()}
function keyOut(){$$('img[data-src]').forEach(img=>{const src=img.dataset.src;delete img.dataset.src;const im=new Image();im.onload=()=>{const N=320,c=document.createElement('canvas');c.width=c.height=N;const x=c.getContext('2d',{willReadFrequently:true});const k=Math.max(N/im.naturalWidth,N/im.naturalHeight),w=im.naturalWidth*k,h=im.naturalHeight*k;x.drawImage(im,(N-w)/2,(N-h)/2,w,h);const d=x.getImageData(0,0,N,N),a=d.data;for(let i=0;i<a.length;i+=4){const r=a[i],g=a[i+1],b=a[i+2],L=(.299*r+.587*g+.114*b)/255;let al=Math.min(1,Math.max(0,(L-.26)/.2));al=Math.max(al,Math.min(1,Math.max(0,(r-g-12)/25)));a[i+3]=al*255}x.putImageData(d,0,0);img.src=c.toDataURL('image/png')};im.src=src})}

