const PERKS=[['💛','10% off the Trio','On your personal Minne Trio purchases. Always.'],['🎁','10% off Morning Boxes','Member price on every future Minne Morning Box: $90 instead of $100.'],['🥄','Recipes from Allie & Maria','Access to a few recipes they choose to share, only with members.'],['🎬','Members-only videos','Preparation videos featuring Allie and Maria in the kitchen.'],['📖','Hosting guides','Serving inspiration and guides to make every gathering easier.'],['⏰','Early access','Be first in line for future offerings.'],['🧪','A say in what’s next','Test new ideas and share your feedback with the team.']];
pages.club=()=>`
<section class="hero2 sub"><div class="w grid g2" style="align-items:center"><div><span class="k">The Minne Club</span><h1 style="margin:14px 0 18px">Gather your people <i>over breakfast.</i></h1><p class="lead">The Minne Club is a way to belong. Members get better prices on the Trio and the Morning Box, hosting guides, and a few recipes and videos Allie and Maria share only with them.</p><div class="cta" style="margin-top:24px"><a class="btn" href="#join" data-scroll="join">Become a Minne Club member</a><a class="btn ghost" href="#vid" data-scroll="vid">Preview a member video</a></div></div><div class="hart"><img class="ph" src="${A('founders.webp')}" alt="Allie and Maria" style="object-position:center 30%"><img class="ph2" src="${A('gr-pour.jpg')}" alt=""><span class="seal"><div><small>Hosted by</small>Allie<br>&amp; Maria</div></span><span class="note hand" style="right:4%;bottom:-2%;--r:-3deg;color:var(--clay)">come on in</span></div></div></section>
${wave('var(--butter)','var(--cream)')}
<section class="sec tight"><div class="w"><div class="stats">${[['10%','off the Trio and Boxes'],['5','ways to gather'],['8–10','guests per Minne Morning'],['2','members-only recipes and videos to start']].map(s=>`<div class="rv"><b>${s[0]}</b><span>${s[1]}</span></div>`).join('')}</div></div></section>
<section class="sec"><div class="w"><div class="sech"><div>${hl('Three ways in','Pick your <i>starting point.</i>')}</div></div><div class="opt3">
<div class="oc rv"><span class="pill" style="align-self:flex-start">Share it</span><h3>The Minne Trio</h3><div class="pr2">$30</div><p>Three bags of Maple Almond Granola. Plus shipping.</p><ul><li>Minne Club member: $27</li><li>First-time gathering guest: $27</li><li>Discounts do not stack</li></ul><a class="btn ghost sm" style="align-self:flex-start;margin-top:auto" href="#/trio">See the Trio</a></div>
<div class="oc ft rv"><span class="pill" style="align-self:flex-start">Host it</span><h3>The Minne Morning Box</h3><div class="pr2">$100</div><p>Host about 8 to 10 people. Plus shipping.</p><ul><li>Minne Club member: $90</li><li>Six bags, hosting guide, bowl cards, activity ideas</li><li>You bring the fresh food and drinks</li></ul><a class="btn pop sm" style="align-self:flex-start;margin-top:auto" href="#/box">Plan a morning</a></div>
<div class="oc rv"><span class="pill" style="align-self:flex-start">Belong to it</span><h3>The Minne Club</h3><div class="pr2" style="font-size:2rem">Membership</div><p>The best prices and a few extras.</p><ul><li>10% off personal Minne Trio purchases</li><li>10% off future Morning Boxes</li><li>Hosting guides and early access</li></ul><a class="btn ghost sm" style="align-self:flex-start;margin-top:auto" href="#join" data-scroll="join">Join the list</a></div></div></div></section>
<section class="sec" style="background:var(--tan)"><div class="w"><div class="sech"><div>${hl('What you get','Seven reasons <i>to join.</i>')}</div></div><div class="grid g4 perks">${PERKS.map((p,i)=>`<div class="act rv${i==0?' hot':''}"><div class="ic" style="background:var(--butter)">${p[0]}</div><h3 style="font-size:1.4rem">${p[1]}</h3><p style="margin-top:6px;color:var(--ink2);font-size:15.5px">${p[2]}</p></div>`).join('')}<div class="act rv" style="background:var(--ink);color:var(--cream);display:grid;align-content:center"><h3 style="font-size:1.6rem">Plus the people.</h3><p style="margin-top:8px;color:#F4E8D2;font-size:15.5px">A table full of friends, a morning worth remembering.</p></div></div></div></section>
<section class="sec"><div class="w grid g2" style="align-items:center"><div class="rv">${hl('Your membership card','Carry it <i>with pride.</i>','Every member gets a MINNEØATS Minne Club card. Show it at pop-ups, and use your member price every time you order.')}<div class="chips" style="margin-top:16px">${['Member pricing','Hosting guides','Members-only content'].map(c=>`<span class="chip on" style="cursor:default">${c}</span>`).join('')}</div></div><div class="cardstack rv"><div class="mcard back"><span class="lg">MINNEØATS</span><div><b>10% off</b> the Minne Trio<br><b>10% off</b> Morning Boxes<br>Recipes &amp; videos</div></div><div class="mcard"><span class="lg">MINNEØATS</span><div><div class="nm">Minne Club Host</div><small>[Member name] · Member since [date]</small></div></div></div></div></section>
<section class="sec" style="background:var(--sky)"><div class="w grid g2" style="align-items:start"><div class="rv">${hl('Hosting','What it means <i>to host.</i>','Hosting a Minne Morning is simple and personal. Here’s what we hope every host does with their box.')}<p style="margin-top:14px;color:var(--ink2)">Members pay the member price on every Morning Box.</p></div><div class="rv"><div class="formbox"><h3 style="margin-bottom:12px">As a host, you</h3><div class="steps">${['Host about 8 to 10 guests within 30 days','Introduce MINNEØATS and share a guest discount','Complete a short feedback form','Optionally share photos or videos, with guests’ permission'].map((s,i)=>`<div class="step" style="background:var(--cream)"><b>${i+1}</b><div style="align-self:center"><p style="font-size:16px;color:var(--ink)">${s}</p></div></div>`).join('')}</div></div></div></div></section>
<section class="sec"><div class="w"><div class="sech"><div>${hl('Hosting experiences','Five ways <i>to gather.</i>','Each suggestion comes with simple instructions, preparation tips and prompts.')}</div></div><div class="grid g5">${ACTS2.map(a=>`<div class="act rv"><div class="ic" style="background:${a[3]}">${a[0]}</div><h3 style="font-size:1.45rem">${a[1]}</h3><p style="font-size:15px;color:var(--ink2);margin-top:6px">${a[2]}</p></div>`).join('')}</div></div></section>
<section class="sec tight" id="vid" style="background:var(--butter2)"><div class="w"><div class="sech"><div>${hl('Members-only preview','A peek inside <i>a member video.</i>','A short teaser of the kind of preparation video members get, with Allie in the kitchen. Filler photos stand in for real footage.')}</div></div><div class="vid" id="vidp"><div class="sc on"><img src="${A('founders.webp')}" alt=""></div><div class="sc"><img src="${A('gr-sheet.jpg')}" alt=""></div><div class="sc"><img src="${A('gr-pour.jpg')}" alt=""></div><div class="sc"><img src="${A('gr-spoon.jpg')}" alt=""></div><div class="sc"><img src="${A('fr-parfait.jpg')}" alt=""></div><div class="shade"></div><span class="badge">Minne Club members · preview</span><div class="cap"><h3 id="vcap">Allie’s kitchen, 7:00 a.m.</h3></div><div class="bar" id="vbar"></div><div class="play"><span>▶</span></div></div><div class="lockbox"><b>The full recipes and videos are for Minne Club members.</b><p>Allie and Maria are sharing just a few, and only with members.</p></div></div></section>
<section class="sec"><div class="w" style="max-width:900px"><div class="sech"><div>${hl('Price at a glance','What members <i>save.</i>')}</div></div><table class="cmp rv"><tr><th></th><th>Regular</th><th>Minne Club member</th><th>First-time gathering guest</th></tr><tr><td>The Minne Trio</td><td>$30</td><td>$27</td><td>$27</td></tr><tr><td>The Minne Morning Box</td><td>$100</td><td>$90</td><td>–</td></tr></table><p style="margin-top:12px;color:var(--mute);font-size:14.5px">Plus shipping. Discounts do not stack.</p></div></section>
<section class="sec" id="join" style="background:var(--butter)"><div class="w" style="max-width:780px"><div class="formbox"><span class="k">Join the Minne Club</span><h2 style="margin:12px 0">Be first <i>through the door.</i></h2><p class="lead" style="margin-bottom:18px">Tell us you’re interested and we’ll let you know when your membership is ready.</p><form data-demo="You’re on the list. (Demo: no email was sent.)"><div class="two"><div class="field"><label>Name *</label><input required></div><div class="field"><label>Email *</label><input type="email" required></div></div><div class="field"><label>Who would you gather? (optional)</label><input placeholder="Friends, a small group, my neighbors…"></div><button class="btn pop">Become a member</button></form></div></div></section>
<section class="sec tight"><div class="w" style="max-width:820px"><div class="sech"><div>${hl('Questions','Club <i>basics.</i>')}</div></div>${qa(['','What does a Minne Morning Box include?','Six bags of Maple Almond Granola, a welcome note from Allie and Maria, a hosting guide and suggested schedule, serving instructions and a topping shopping list, Build Your Signature Bowl cards, activity suggestions and discussion prompts, guest discount information with an ordering QR code, a feedback form and branded packaging.'])}${qa(['','What do hosts bring?','Fresh ingredients, drinks, serving items and materials for your chosen activity. The box offers inspiration and guidance, not complete activity kits.'])}${qa(['','Are the recipes public?','No. Allie and Maria are sharing just a few recipes, and only with Minne Club members.'])}${qa(['','How much does shipping cost?','[Shipping time and cost to be confirmed.]'])}</div></section>`;
function clubInit(){const v=$('#vidp');if(!v)return;const caps=['Allie’s kitchen, 7:00 a.m.','Spread it on the sheet pan…','Toss in the maple and let it bake slow','Taste the first clusters','Build your bowl. Want the whole morning?'];let i=0,t0=0;const sc=$$('.sc',v),bar=$('#vbar');const set=n=>{i=n;sc.forEach((s,k)=>s.classList.toggle('on',k===n));$('#vcap').textContent=caps[n]};v.onclick=()=>{if(v.classList.contains('run'))return;v.classList.add('run');t0=performance.now();const tick=n=>{const e=(n-t0)/1000;bar.style.width=Math.min(100,e/20*100)+'%';const k=Math.min(4,Math.floor(e/4));if(k!==i)set(k);if(e<20)requestAnimationFrame(tick);else{v.classList.remove('run');set(0);bar.style.width='0'}};requestAnimationFrame(tick)}}

