pages.gifts=()=>ph('Gifts','Granola makes <i>a good gift.</i>','Gift cards, a maple almond candle, a mug and a tote you can send today, plus a few gift boxes on the way.')+`<section class="sec tight"><div class="w"><div class="grid g4">${['gift','candle','mug','tote'].map(i=>pcard(prod(i))).join('')}<div class="pc rv" style="background:var(--butter);border:0"><div class="bd" style="justify-content:center;gap:10px"><span class="hand">also try</span><h3>The Minne Trio</h3><p style="color:var(--ink2)">Three bags in one order. A gift for yourself, plus two to give.</p><div class="row"><a class="btn sm" href="#/trio">See the Trio</a></div></div></div></div></div></section>
<section class="sec" style="background:var(--tan)"><div class="w"><div class="sech"><div>${hl('Coming soon','Gift boxes, <i>wrapped up.</i>','Every box arrives in a sturdy, hard-sided box with the MINNEØATS logo, tissue paper, ribbon and a personal-message card.')}</div></div><div class="grid g3">${[['Classic Gift Box','Granola, honey, a serving card, a personal message and a future-purchase discount.','var(--butter)'],['Minne Trio Gift Box','Three bags packaged for gifting, with a seasonal flavor option once available.','var(--sky)'],['Corporate Gifts','Bulk orders with company message cards or branded gift tags.','var(--cream)']].map(g=>`<div class="oc rv" style="background:${g[2]};border:0"><span class="pill" style="align-self:flex-start">Coming soon</span><h3>${g[0]}</h3><p>${g[1]}</p><p style="font-size:14px;color:var(--ink2)">[Prices, minimum quantities and lead times coming soon.]</p></div>`).join('')}</div></div></section>
<section class="sec tight"><div class="w"><div class="band sky rv"><div><span class="k">Seasonal flavors · coming up</span><h2 style="margin:12px 0">Four seasons, <i>one favorite.</i></h2><p class="lead">Maple Almond stays year-round. We’re dreaming up a flavor for every season.</p></div><div class="grid g2" style="gap:12px">${[['Winter','Gingerbread Spice'],['Spring','Lemon Blueberry'],['Summer','Mango Coconut'],['Fall','Apple Cinnamon']].map(f=>`<div style="background:var(--cream);border-radius:18px;padding:16px 18px"><span class="k" style="font-size:11px">${f[0]}</span><div style="font:600 1.4rem var(--serif);margin-top:6px">${f[1]}</div></div>`).join('')}</div></div></div></section>
<section class="sec tight"><div class="w" style="max-width:760px"><div class="formbox"><h3>Interested in corporate gifting?</h3><p style="color:var(--ink2);margin:8px 0 16px">Tell us what you have in mind and we’ll be in touch.</p><form data-demo="Thank you! (Demo: your inquiry wasn’t actually sent.)"><div class="two"><div class="field"><label>Name *</label><input required></div><div class="field"><label>Email *</label><input type="email" required></div></div><div class="field"><label>Company and rough quantity</label><input></div><button class="btn">Send inquiry</button></form></div></div></section>`;

