const TRY=[['On toast','try-toast.jpg','Almond butter, banana, then a handful of crunch.'],['On pancakes','try-pancakes.jpg','Over the syrup, while the stack is still warm.'],['On waffles','gr-maple.jpg','Warm waffles, a drizzle of maple, then a handful of crunch.'],['Over cottage cheese','try-cottage.jpg','Creamy and crunchy, with a few berries.'],['On baked apples','try-apples.jpg','A cozy, cinnamon-warm topping.'],['On overnight oats','try-overnight.jpg','Add it just before you eat so it stays crisp.'],['On fresh berries','way-berries.jpg','Sweet, tart and crunchy.'],['In a fruit bowl','try-coconut.jpg','Fruit, yogurt and a scoop on top.'],['On ice cream','way-icecream.jpg','A crunchy topping.'],['With cold milk','gr-pour.jpg','The classic.'],['On yogurt','way-yogurt.jpg','Thick, creamy and crunchy.'],['In a parfait','fr-parfait.jpg','Layered with fruit.']];
function trySection(){return `<section class="sec" style="background:var(--butter2)"><div class="w"><div class="sech"><div><span class="k">A scoop goes a long way</span><h2>Every <i>which way.</i></h2><p>We keep our recipes to ourselves, but we love sharing ideas. Here’s how granola lands on your favorites.</p></div></div><div class="tryrow">${TRY.map(t=>`<figure class="trycard rv"><img src="${A(t[1])}" alt="" loading="lazy"><figcaption><b>${t[0]}</b><span>${t[2]}</span></figcaption></figure>`).join('')}</div></div></section>`}
const BUNDLE=[['oz10','10 oz Maple Almond','cut-10oz.webp',12],['oz4','4 oz Take-along','cut-4oz.webp',5],['candle','Maple Almond Candle','cut-candle.webp',25],['mug','Diner Mug','cut-mug.webp',10],['tote','Canvas Tote','p-tote-life.webp',15]];
function bundleHTML(){return `<section class="sec" id="bundle" style="background:var(--tan)"><div class="w"><div class="sech"><div><span class="k">Choose your own adventure</span><h2>Build your own <i>bundle.</i></h2><p>Pick your favorites, then add a free custom note for the gift.</p></div></div><div class="grid g5 bund">${BUNDLE.map(b=>`<div class="act bi"><img src="${A(b[2])}" alt="" loading="lazy"><h4>${b[1]}</h4><p>${price(b[3])}</p><div class="qty" data-b="${b[0]}"><button data-d="-1" aria-label="Fewer">−</button><span>0</span><button data-d="1" aria-label="More">+</button></div></div>`).join('')}</div><div class="bundbar"><div><b id="bsum">Pick something above to start your bundle.</b><div class="field" style="margin:10px 0 0"><label>Free custom note (optional, up to 250 characters)</label><textarea id="bnote" maxlength="250" rows="2" placeholder="Happy birthday! Love, …"></textarea></div></div><button class="btn pop" id="badd" disabled>Add bundle to bag</button></div></div></section>`}
function bundleInit(){const root=$('#bundle');if(!root)return;const q={};const draw=()=>{const items=BUNDLE.filter(b=>q[b[0]]>0),n=items.reduce((a,b)=>a+q[b[0]],0),t=items.reduce((a,b)=>a+q[b[0]]*b[3],0);$('#bsum').textContent=n?`${n} item${n>1?'s':''} · ${money(t)}`:'Pick something above to start your bundle.';$('#badd').disabled=!n;$$('.qty',root).forEach(e=>{e.querySelector('span').textContent=q[e.dataset.b]||0})};root.addEventListener('click',e=>{const b=e.target.closest('[data-d]');if(b){const id=b.parentElement.dataset.b;q[id]=Math.max(0,(q[id]||0)+(+b.dataset.d));draw();return}if(e.target.id==='badd'){const note=$('#bnote').value.trim();let first=true;BUNDLE.forEach(x=>{if(q[x[0]]>0){add(x[0],null,q[x[0]],false,null,first?note:'');first=false}})}});draw()}
const _shop=pages.shop;pages.shop=a=>_shop(a)+trySection()+bundleHTML();
pages.donate=()=>ph('Giving back','Donation <i>requests.</i>','We believe in the importance of community and supporting organizations that make a meaningful impact.')+`<section class="sec tight"><div class="w" style="max-width:820px"><div class="formbox"><p style="color:var(--ink2)">[Add a sentence about how Allie and Maria approach giving, since they receive many requests each year.]</p><p style="color:var(--ink2);margin-top:12px">Our standard donation is <b>[a gift card, bags of granola, or another item]</b>. If you would like to request a donation, please review the guidelines below and fill out the form.</p><ul class="dn-l" style="margin:16px 0 20px;padding-left:20px;display:grid;gap:8px;color:var(--ink2)"><li>The requesting organization must be [a registered non-profit].</li><li>The event must benefit [people in the service area].</li><li>Requests must be submitted at least <b>[one month]</b> in advance.</li><li>We accept <b>[one request per organization per year]</b>.</li><li>Please submit your request through the online form.</li><li>Donations are limited each month. If we can fulfill your request, we’ll email you within [5–7 days].</li></ul><p class="hand" style="font-size:1.4rem;margin-bottom:18px">[These guidelines are placeholders until Allie and Maria confirm their policy.]</p><h3>Donation request</h3><form data-demo="Thank you! (Demo: your request wasn’t actually sent.)" style="margin-top:14px"><div class="two"><div class="field"><label>Full name *</label><input required></div><div class="field"><label>Email of representative *</label><input type="email" required></div></div><div class="field"><label>Organization or charity you’re requesting for *</label><input required></div><div class="two"><div class="field"><label>Website of organization</label><input></div><div class="field"><label>Date of event</label><input></div></div><div class="field"><label>Event name &amp; location</label><input></div><div class="field"><label>Tell us about the event and what you’re requesting</label><textarea rows="4"></textarea></div><button class="btn">Send request</button></form></div></div></section>`;
function welcomePop(){try{if(sessionStorage.getItem('mo2pop'))return;sessionStorage.setItem('mo2pop','1')}catch(e){}if($('#drawer').classList.contains('on')||$('#modal').classList.contains('on'))return;modal('ph-yogurt-bright.webp',`<span class="k">Join MINNEØATS Monthly</span><h2 style="font-size:2.5rem;margin:12px 0">Get 15% off <i>your first order.</i></h2><p style="color:var(--ink2);margin-bottom:16px">Subscribe for first looks at new flavors and the inside scoop. The offer applies to one-time purchases (subscriptions already save 10%).</p><form data-demo="You’re in! Your 15% off code is on its way. (Demo: no email was sent.)"><div class="field"><label>Email address</label><input type="email" required placeholder="you@example.com"></div><button class="btn wide pop">Get 15% off</button></form><button id="nothx" style="background:none;border:0;cursor:pointer;margin-top:14px;font:inherit;color:var(--mute);text-decoration:underline">No thanks</button>`)}
document.addEventListener('click',e=>{if(e.target.id==='nothx')closeAll()});
setTimeout(welcomePop,600);

/* ---------- plan your morning: bowl name, invitation, gathering list ---------- */
const PLAN_ACTS=['Build Your Signature Bowl','Bouquets & Breakfast','Notes of Encouragement','Brunch & Books','Faith & Fellowship'];
function planHTML(){return `<section class="sec" id="plan" style="background:var(--butter2)"><div class="w"><div class="sech"><div><span class="k">Try it now</span><h2>Plan your morning, <i>just for fun.</i></h2><p>Name your signature bowl, write your invitation and see what to gather. Nothing is saved or sent.</p></div></div>
<div class="grid g3 tools3">
<div class="tc rv"><span class="k">1 · Build your bowl</span><p class="tsm">Pick a base and a few toppings. Maple Almond Granola is always on top.</p><div class="chips" id="bbBase" role="radiogroup" aria-label="Base"></div><div class="chips" id="bbTop" aria-label="Toppings"></div><div class="field"><label>Name your bowl</label><input id="bbName" maxlength="34" placeholder="e.g. Sunrise on Lake Street" autocomplete="off"></div><button class="btn ghost sm" id="bbIdea" type="button">Surprise me with a name</button><div class="namecard" aria-live="polite"><small>Signature bowl</small><b id="bbOut">Your bowl’s name</b><span id="bbSub">Pick a base to begin</span><i>Built by <u id="bbBy">[your name]</u> · Minne Morning</i></div><div class="field"><label>Your name (for the card)</label><input id="bbWho" maxlength="24" placeholder="Your name" autocomplete="off"></div></div>
<div class="tc rv"><span class="k">2 · Write your invitation</span><div class="field"><label>Activity</label><select id="ivAct">${PLAN_ACTS.map(a=>`<option>${a.replace('&','&amp;')}</option>`).join('')}</select></div><div class="two"><div class="field"><label>Date</label><input id="ivDate" placeholder="Saturday, [date]"></div><div class="field"><label>Time</label><input id="ivTime" placeholder="[time]"></div></div><div class="field"><label>Anything guests should bring or read</label><input id="ivExtra" placeholder="Optional"></div><div class="invite2" id="ivOut" aria-live="polite"></div><button class="btn sm" id="ivCopy" type="button">Copy invitation</button> <span class="tsm" id="ivMsg" role="status"></span></div>
<div class="tc rv"><span class="k">3 · Your gathering list</span><div class="field"><label>Guests: <b id="slN">9</b></label><input id="slRange" type="range" min="8" max="10" value="9"></div><h4>In your box</h4><ul class="tl2" id="slIn"></ul><h4>You bring</h4><ul class="tl2" id="slBring"></ul><p class="tsm">Exact serving amounts are still being tested, so there are no quantities here yet.</p></div>
</div></div></section>`}
function planInit(){if(!$('#plan'))return;const g=id=>document.getElementById(id);const bases=['Warm oatmeal','Yogurt','Cold milk'],tops=['Blueberries','Strawberries','Banana','Apple','Honey','Cinnamon'],words=['Sunrise','Hug','Morning','Dream','Special','Sunday'];let base=null,sel=[];
 const chip=(t,on,fn)=>{const b=document.createElement('button');b.type='button';b.className='chip'+(on?' on':'');b.textContent=t;b.setAttribute('aria-pressed',on);b.onclick=fn;return b};
 const card=()=>{g('bbOut').textContent=g('bbName').value.trim()||'Your bowl’s name';g('bbSub').textContent=base?base+(sel.length?' · '+sel.join(' · '):'')+' · Maple Almond Granola':'Pick a base to begin';g('bbBy').textContent=g('bbWho').value.trim()||'[your name]'};
 const drawB=()=>{const bb=g('bbBase'),bt=g('bbTop');bb.innerHTML='';bases.forEach(x=>bb.appendChild(chip(x,base===x,()=>{base=x;drawB();card()})));bt.innerHTML='';tops.forEach(x=>{const on=sel.includes(x);bt.appendChild(chip(x,on,()=>{const i=sel.indexOf(x);if(i>-1)sel.splice(i,1);else sel.push(x);drawB();card()}))})};
 g('bbName').oninput=card;g('bbWho').oninput=card;g('bbIdea').onclick=()=>{const t=sel.length?sel[Math.floor(Math.random()*sel.length)]:(base||'Maple');g('bbName').value='The '+({Blueberries:'Blueberry',Strawberries:'Strawberry'}[t]||t)+' '+words[Math.floor(Math.random()*words.length)];card()};drawB();card();
 const inv=()=>{const a=g('ivAct').value,d=g('ivDate').value.trim()||'[date]',t=g('ivTime').value.trim()||'[time]',x=g('ivExtra').value.trim();g('ivOut').textContent='“Come over for breakfast and a little time together! I’m hosting a Minne Morning with MINNEØATS granola, coffee, and '+a+'. I’d love for you to join us on '+d+' at '+t+'.'+(x?' '+x:'')+'”'};
 ['ivAct','ivDate','ivTime','ivExtra'].forEach(i=>{g(i).oninput=inv;g(i).onchange=inv});inv();
 g('ivCopy').onclick=()=>{const m=g('ivMsg');try{navigator.clipboard.writeText(g('ivOut').textContent).then(()=>{m.textContent='Copied.'},()=>{m.textContent='Select the text and copy it.'})}catch(e){m.textContent='Select the text and copy it.'}};
 const inc={'Build Your Signature Bowl':[],'Bouquets & Breakfast':['Arrangement instructions','Gift tags'],'Notes of Encouragement':['Notecards','Envelopes','Writing prompts'],'Brunch & Books':['Discussion cards','Bookmarks'],'Faith & Fellowship':['Short Bible study guide','Reflection cards','Prayer-request cards']};const extra={'Bouquets & Breakfast':'Flowers, jars and flower-cutting tools','Brunch & Books':'The book (tell guests ahead of time)'};
 const li=a=>a.map(x=>'<li>'+x+'</li>').join('');const list=()=>{const a=g('ivAct').value,n=g('slRange').value;g('slN').textContent=n;g('slIn').innerHTML=li(['Six bags of Maple Almond Granola','Welcome note from Allie and Maria','Hosting guide and suggested schedule','Build Your Signature Bowl cards','Guest discount card and ordering QR code','Feedback form'].concat(inc[a]||[]));g('slBring').innerHTML=li(['Yogurt, fruit and milk','Coffee or other drinks for '+n+' guests','Bowls, utensils and serving dishes',extra[a]||'Anything listed with your activity'])};
 g('slRange').oninput=list;g('ivAct').addEventListener('change',list);list()}
const _club=pages.club,_box=pages.box,_mk='<section class="sec tight"><div class="w" style="max-width:820px">';
pages.club=()=>_club().replace(_mk,planHTML()+_mk);pages.box=()=>_box().replace(_mk,planHTML()+_mk);

/* ---------- cover ---------- */
function coverHTML(){return `<section class="cover cd"><div class="w"><div class="cv-t"><span class="k">Small-batch granola · Blaine, Minnesota</span><h1>From bowl <i>to soul.</i></h1><p class="lead">Maple almond granola, handcrafted in small batches since 2017, and delivered on your schedule.</p><div class="cta"><a class="btn" href="#/shop">Shop granola</a><a class="btn ghost" href="#/subscribe">Subscribe &amp; save 10%</a></div></div><div class="cv-spill"><div class="disc"></div><img src="${A('cut-spill.webp')}" alt="A MINNEØATS Maple Almond Granola pouch with golden granola clusters spilling out"></div></div></section>`}

/* ---------- init hooks ---------- */
const _route2=route;route=function(){_route2();bowlInit();bundleInit();planInit();keyOut();if(location.hash.includes('/'))$$('.hdr .nav a').forEach(a=>{const h=location.hash.replace(/^#\/?/,'').split('/')[0];a.classList.toggle('on',a.dataset.n===h||(a.dataset.n==='club'&&['trio','box'].includes(h)))})};
boot();
